"use client"

import type * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export default function Cta({
  className,
  ...props
}: React.ComponentProps<"section">) {
  return (
    <section
      className={cn("w-full px-3 py-6 sm:px-4 md:px-8 md:py-8", className)}
      aria-labelledby="cta-heading"
      {...props}
    >
      <style>{`
        .cta-01-card {
          background-color: #f3f4f6;
        }
        .dark .cta-01-card {
          background-color: #262626;
        }
      `}</style>

      <div className="cta-01-card mx-auto w-full max-w-5xl rounded-[12px] p-5 shadow-soft sm:p-6 md:p-8">
        <div className="max-w-4xl text-start">
          <h2
            id="cta-heading"
            className="mb-4 text-[1.75rem] font-bold tracking-tight text-foreground sm:mb-6 sm:text-3xl md:text-4xl"
          >
            Hello World!
          </h2>
          <p className="text-base leading-relaxed text-muted-foreground">
            Start building faster with our collection of ready-made UI
            components. Clean design, fully responsive, and easy to customize
            for any project.
          </p>
          <Button asChild className="mt-6 h-[46px] rounded-[12px] sm:mt-8">
            <a href="#">Get started</a>
          </Button>
        </div>
      </div>
    </section>
  )
}
